[2] atk:startAuction[fail:Ownable: caller is not the owner] | +0.4r +5br | signal=N | desc="Start the auction."
[3] atk:bid[fail:Bid must be at least 0.25 ETH higher than the highest bid] | +0.0r +0br | signal=N | desc="The attacker calls bid() to place a bid and starts the auction."
[4] atk:buyNow[fail:Invalid funds provided] | +0.0r +0br | signal=N | desc="The attacker calls buyNow() to bid on the auction and ends the auction with all…"
